begin;
insert into auth.users values ('00000000-0000-4000-8000-000000000001','a@example.com',now()),('00000000-0000-4000-8000-000000000002','b@example.com',now()),('00000000-0000-4000-8000-000000000003','member@example.com',now());
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.create_workspace('Firm A') as firm_a \gset
insert into public.agents(id,firm_id,name,phone) values('10000000-0000-4000-8000-000000000001',:'firm_a','Agent A','+60123456789'),('10000000-0000-4000-8000-000000000002',:'firm_a','Agent B','+60987654321');
insert into public.cases(id,firm_id,ref,buyer,type,status,priority,agent_id,notes) values ('20000000-0000-4000-8000-000000000001',:'firm_a','A-001','Private buyer','SPA','loan','normal','10000000-0000-4000-8000-000000000001','Private legal note'),('20000000-0000-4000-8000-000000000002',:'firm_a','B-SECRET','Other buyer','SPA','spa','normal','10000000-0000-4000-8000-000000000002','Other private note');
select public.configure_whatsapp('{"account_id":"account-a","enabled":true,"dry_run":true}');
select public.rotate_whatsapp_worker(repeat('a',64));
insert into public.whatsapp_contacts values(:'firm_a','10000000-0000-4000-8000-000000000001','+60123456789',true,true);
insert into public.whatsapp_rules(firm_id,case_id,enabled) values(:'firm_a','20000000-0000-4000-8000-000000000001',true);
select tests.denied('select * from casetrack_private.whatsapp_tokens','42501','owners cannot retrieve worker token hashes');
select public.invite_member('member@example.com');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.accept_invitation((select id from public.pending_invitations() limit 1));
select tests.assert((select count(*)=0 from public.whatsapp_contacts),'members cannot read WhatsApp allowlist');
select tests.denied($q$select public.configure_whatsapp('{"account_id":"hijack"}')$q$,'P0001','member cannot reconfigure account');
select tests.denied($q$select public.rotate_whatsapp_worker(repeat('b',64))$q$,'P0001','member cannot rotate worker credential');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.create_workspace('Firm B') as firm_b \gset
select tests.assert((select count(*)=0 from public.whatsapp_settings),'other firm cannot read integration');
select public.configure_whatsapp('{"account_id":"account-b","enabled":true}');
select public.rotate_whatsapp_worker(repeat('b',64));
reset role;set role anon;
select tests.denied('select * from public.whatsapp_settings','42501','anon cannot read integration tables');
select tests.denied($q$select public.whatsapp_worker(repeat('c',64),'poll')$q$,'P0001','invalid token rejected');
select tests.denied($q$select casetrack_private.whatsapp_context(null,'+60123456789')$q$,'42501','private context cannot be called directly');
select tests.assert(public.whatsapp_worker(repeat('a',64),'poll')->>'account_id'='account-a','token scoped to one workspace');
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-b","phone":"+60123456789"}') is null,'wrong account denied');
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60000000000"}') is null,'unknown number denied');
select tests.assert(jsonb_array_length(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60123456789"}')->'cases')=1,'registered number sees only its assigned case');
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60123456789"}')::text !~ 'Private|buyer|notes|B-SECRET','private fields and foreign references excluded');
select tests.assert(public.whatsapp_worker(repeat('b',64),'context','{"account_id":"account-b","phone":"+60123456789"}') is null,'another workspace token cannot resolve agent');
select tests.assert(public.whatsapp_worker(repeat('a',64),'claim','{"account_id":"account-a","phone":"+60123456789","event_key":"foreign","kind":"followup","case_id":"20000000-0000-4000-8000-000000000002"}') is null,'foreign case follow-up denied');
select public.whatsapp_worker(repeat('a',64),'claim','{"account_id":"account-a","phone":"+60123456789","event_key":"in:one","kind":"reply"}')->>'id' as event_id \gset
select tests.assert(:'event_id' is not null,'valid event reserved');
select tests.assert(public.whatsapp_worker(repeat('a',64),'claim','{"account_id":"account-a","phone":"+60123456789","event_key":"in:one","kind":"reply"}') is null,'duplicate reservation blocked');
select tests.assert(public.whatsapp_worker(repeat('a',64),'claim','{"account_id":"account-a","phone":"+60123456789","event_key":"in:two","kind":"reply"}') is null,'per-number rate limit enforced');
reset role;set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
update public.cases set agent_id='10000000-0000-4000-8000-000000000002' where id='20000000-0000-4000-8000-000000000001';
reset role;set role anon;
select tests.assert(jsonb_array_length(public.whatsapp_worker(repeat('a',64),'authorize',jsonb_build_object('account_id','account-a','phone','+60123456789','id',:'event_id'))->'context'->'cases')=0,'send authorization rechecks reassignment');
select public.whatsapp_worker(repeat('a',64),'optout','{"account_id":"account-a","phone":"+60123456789","event_key":"stop:one"}');
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60123456789"}') is null,'STOP revokes agent access');
reset role;set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
update public.whatsapp_contacts set enabled=true,consent=true;
reset role;set role anon;
select public.whatsapp_worker(repeat('a',64),'optout','{"account_id":"account-a","phone":"+60123456789","event_key":"stop:one"}');
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60123456789"}') is not null,'old STOP is not replayed after explicit reapproval');
reset role;set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
update public.agents set phone='+60111111111' where id='10000000-0000-4000-8000-000000000001';
reset role;set role anon;
select tests.assert(public.whatsapp_worker(repeat('a',64),'context','{"account_id":"account-a","phone":"+60123456789"}') is null,'changed on-file phone invalidates old approval');
reset role;set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.configure_whatsapp('{"account_id":"account-a","enabled":false}');
reset role;set role anon;
select tests.assert(public.whatsapp_worker(repeat('a',64),'authorize',jsonb_build_object('account_id','account-a','phone','+60123456789','id',:'event_id')) is null,'pause blocks send authorization');
reset role;set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.rotate_whatsapp_worker(repeat('d',64));
reset role;set role anon;
select tests.denied($q$select public.whatsapp_worker(repeat('a',64),'poll')$q$,'P0001','rotated token immediately invalid');
reset role;rollback;
